@startuml

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... (other categories)
}

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + EmailAddress : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + StorageSpace : int
  + AvailableDays : date[]
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : date[]
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class H2SEmployee {
  + FirstName : string
  + LastName : string
  + RFIDDevice : bool
}

class PickupRoute {
  + Date : date
}

class ScheduledPickup {
  + Time : time
  + Resident : Resident
  + PickupVehicle : PickupVehicle
  + VolunteerDriver : VolunteerDriver
  + ItemsDescription : string
  + Category : ItemCategory[]
}

class Client {
  + Name : string
  + Address : string
  + NeededCategories : ItemCategory[]
}

class DeliveredArticle {
  + ArticleId : int
  + Category : ItemCategory
  + Client : Client
}

PickupVehicle "1" -- "*" PickupRoute
VolunteerDriver "1" -- "*" PickupRoute
Resident --|> ScheduledPickup
PickupVehicle --|> ScheduledPickup
VolunteerDriver --|> ScheduledPickup
DistributionCenter "1" -- "*" ScheduledPickup : receives second hand articles
FoodBank "1" -- "*" ScheduledPickup : receives non-perishable foods
H2SEmployee "1" -- "*" ScheduledPickup : examines quality and assigns categories
Client "0..*" -- "*" DeliveredArticle : needs articles
H2SEmployee "1" -- "*" DeliveredArticle : calls clients to arrange delivery

@enduml

